// Package access implements Phase 1 Step 3 (user registration, access policy,
// access tokens) and the claim check behind VerifyAccess (Phase 1 Step 2
// item 1, Eq. 21).
//
// Token issuance (Q6 ruling, B7 rejected): Step 3.2 Generate_User_Token is
// internally inconsistent. It decrypts a Policy that holds only
// H(UserID)/H(Permissions) (Eq. 5) and then needs the plaintext values, which a
// hash can't give back. The on-chain Policy stays exactly Eq. 5. Tokenu
// (Eq. 7) is generated by the trusted registration/token authority in
// RegisterUser, while it still holds the plaintext registration inputs.
//
// VerifyAccess (Q1 ruling): Tokenu is decrypted with Kauth off-chain. The
// resulting Claims are checked against the on-chain policy by the contract.
// CheckClaims is the Go statement of that contract check; contracts/
// VerifyAccess.sol implements the same check in Solidity.
//
// The policy commitment (Q11 ruling) is a minimal EVM compatibility
// mechanism, NOT an EVSEB-defined construction. It hides the Eq. 5 fields only
// in stored contract state. Claims sent to verifyAccess as a transaction are
// public calldata, so no policy confidentiality is claimed for them.
package access

import (
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"slices"
	"time"

	"evseb/internal/crypto"
)

// Status strings returned by Register_User (Step 3.1 lines 4, 10).
const (
	StatusAuthFailed = "Authentication Failed"
	StatusRegistered = "User Registered Successfully"
)

// AccessPolicy is Eq. 5: Policy = {H(UserID), H(Permissions), H(LType), Texp}.
type AccessPolicy struct {
	HUserID      [32]byte
	HPermissions [32]byte
	HLType       [32]byte
	Texp         int64 // Unix seconds
}

// UserToken is the plaintext of Tokenu = EncAES(UserID || Permissions || Texp,
// Kauth) (Eq. 4, 7). Permissions is the list of authorized LType values (B6).
type UserToken struct {
	UserID      string
	Permissions []string
	Texp        int64 // Unix seconds
}

// HashPermissions is H(Permissions): SHA-256 of the Permissions encoding (a
// 4-byte big-endian count, then each LType as 4-byte big-endian length +
// bytes).
func HashPermissions(perms []string) [32]byte { return crypto.H(encodePermissions(nil, perms)) }

// NewPolicy builds Eq. 5.
func NewPolicy(userID string, permissions []string, lType string, texp int64) AccessPolicy {
	return AccessPolicy{
		HUserID:      crypto.H([]byte(userID)),
		HPermissions: HashPermissions(permissions),
		HLType:       crypto.H([]byte(lType)),
		Texp:         texp,
	}
}

// Encode is the fixed 104-byte pre-encryption form of a Policy:
// H(UserID) || H(Permissions) || H(LType) || Texp (int64 big-endian).
func (p AccessPolicy) Encode() []byte {
	b := make([]byte, 0, 104)
	b = append(b, p.HUserID[:]...)
	b = append(b, p.HPermissions[:]...)
	b = append(b, p.HLType[:]...)
	return binary.BigEndian.AppendUint64(b, uint64(p.Texp))
}

// DecodePolicy reverses Encode.
func DecodePolicy(b []byte) (AccessPolicy, error) {
	var p AccessPolicy
	if len(b) != 104 {
		return p, errors.New("access: bad policy encoding")
	}
	copy(p.HUserID[:], b[0:32])
	copy(p.HPermissions[:], b[32:64])
	copy(p.HLType[:], b[64:96])
	p.Texp = int64(binary.BigEndian.Uint64(b[96:]))
	return p, nil
}

// Commitment is C = SHA-256(Policy.Encode()). It is stored on-chain next to
// CTPolicy so the contract can check claims against the Eq. 5 Policy without
// reading the ciphertext. C is a minimal EVM compatibility mechanism, not an
// EVSEB construction (QUESTIONS.md Q11).
func (p AccessPolicy) Commitment() [32]byte { return sha256.Sum256(p.Encode()) }

// EncryptPolicy is Eq. 6: CTPolicy = EncAES(Policy, Kindex).
func EncryptPolicy(p AccessPolicy, kindex [32]byte) ([]byte, error) {
	return crypto.EncAES(p.Encode(), kindex)
}

// DecryptPolicy is DecAES(CTPolicy, Kindex) (Step 3.2 line 3).
func DecryptPolicy(ct []byte, kindex [32]byte) (AccessPolicy, error) {
	pt, err := crypto.DecAES(ct, kindex)
	if err != nil {
		return AccessPolicy{}, err
	}
	return DecodePolicy(pt)
}

// Encode serializes UserID || Permissions || Texp. Strings are a 4-byte
// big-endian length followed by the bytes; Permissions is a 4-byte count
// followed by each string; Texp is int64 big-endian. (The paper gives no
// concatenation format for "||"; this one is unambiguous to parse.)
func (t UserToken) Encode() []byte {
	b := appendString(nil, t.UserID)
	b = encodePermissions(b, t.Permissions)
	return binary.BigEndian.AppendUint64(b, uint64(t.Texp))
}

// DecodeToken reverses UserToken.Encode.
func DecodeToken(b []byte) (UserToken, error) {
	var t UserToken
	var ok bool
	if t.UserID, b, ok = readString(b); !ok {
		return t, errBadToken
	}
	if len(b) < 4 {
		return t, errBadToken
	}
	n := binary.BigEndian.Uint32(b)
	b = b[4:]
	if uint64(n) > uint64(len(b)) { // each entry needs >= 4 bytes; cheap sanity bound
		return t, errBadToken
	}
	for range n {
		var s string
		if s, b, ok = readString(b); !ok {
			return t, errBadToken
		}
		t.Permissions = append(t.Permissions, s)
	}
	if len(b) != 8 {
		return t, errBadToken
	}
	t.Texp = int64(binary.BigEndian.Uint64(b))
	return t, nil
}

var errBadToken = errors.New("access: bad token encoding")

// EncryptToken is Eq. 4 / Eq. 7: Tokenu = EncAES(UserID || Permissions || Texp, Kauth).
func EncryptToken(t UserToken, kauth [32]byte) ([]byte, error) {
	return crypto.EncAES(t.Encode(), kauth)
}

// DecryptToken decrypts Tokenu with Kauth.
func DecryptToken(ct []byte, kauth [32]byte) (UserToken, error) {
	pt, err := crypto.DecAES(ct, kauth)
	if err != nil {
		return UserToken{}, err
	}
	return DecodeToken(pt)
}

// Claims are the authorization claims the off-chain verifier sends to the
// VerifyAccess contract (Q1 ruling). HUserID = H(UserID), Permissions and Texp
// come from Tokenu decrypted with Kauth. HLType comes from the user's on-chain
// CTPolicy decrypted with Kindex (as Step 3.2 lines 2-3 do). The plaintext
// UserID is not a claim: the on-chain record is keyed by H(UserID) (Q11).
type Claims struct {
	HUserID     [32]byte
	Permissions []string
	Texp        int64
	HLType      [32]byte
}

// ErrNoClaims means the token or policy could not be turned into claims: the
// token failed to decrypt or decode, the policy failed to decrypt, or the
// policy belongs to a different user.
var ErrNoClaims = errors.New("access: token/policy do not yield valid claims")

// BuildClaims is the off-chain half of VerifyAccess: tok is Tokenu already
// decrypted with Kauth, ctPolicy is the user's on-chain CTPolicy.
func BuildClaims(tok UserToken, ctPolicy []byte, kindex [32]byte) (Claims, error) {
	p, err := DecryptPolicy(ctPolicy, kindex)
	hUser := crypto.H([]byte(tok.UserID))
	if err != nil || p.HUserID != hUser {
		return Claims{}, ErrNoClaims
	}
	return Claims{HUserID: hUser, Permissions: tok.Permissions, Texp: tok.Texp, HLType: p.HLType}, nil
}

// CheckClaims is the on-chain half of VerifyAccess, as VerifyAccess.sol
// computes it. It allows iff the claims reproduce the stored Policy
// commitment, now <= Texp, and LType is among the claimed Permissions.
func CheckClaims(c Claims, commitment [32]byte, lType string, now int64) bool {
	p := AccessPolicy{HUserID: c.HUserID, HPermissions: HashPermissions(c.Permissions),
		HLType: c.HLType, Texp: c.Texp}
	return p.Commitment() == commitment && now <= c.Texp && slices.Contains(c.Permissions, lType)
}

// AccessVerifier is the VerifyAccess contract as seen by the Search Engine.
type AccessVerifier interface {
	VerifyAccess(tokenCT []byte, lType string) (bool, error)
}

// VerifyAccess is Eq. 21; it delegates to the VerifyAccess contract.
func VerifyAccess(v AccessVerifier, tokenCT []byte, lType string) (bool, error) {
	return v.VerifyAccess(tokenCT, lType)
}

// PolicyStore is Blockchain_Store (Step 3.1 line 9; grantAccess, Table 3).
type PolicyStore interface {
	GrantAccess(userID string, policyCT []byte) error
}

// Registrar is the trusted Registration Authority / token authority of
// Phase 1 Step 3.
type Registrar struct {
	Chain  PolicyStore
	Kindex [32]byte
	Kauth  [32]byte
	// VerifyCredentials is Verify_Credentials (Step 3.1 line 2). The paper
	// does not say what credentials are or how they are checked, so the
	// check is supplied by the caller.
	VerifyCredentials func(userID, credentials string) bool
	// Validity is added to Now to produce Texp
	// (Generate_Expiration_Timestamp, Step 3.1 line 6; period unspecified).
	Validity time.Duration
	Now      func() time.Time
}

// RegisterUser is Register_User (Step 3.1). After storing CTPolicy it issues
// Tokenu = EncAES(UserID || Permissions || Texp, Kauth) (Eq. 7) from the
// plaintext inputs it still holds (Q6 ruling). On failed credentials it
// returns StatusAuthFailed and no token. err is non-nil only for
// encryption/storage failures.
func (r *Registrar) RegisterUser(userID, credentials string, permissions []string, lType string) (string, []byte, error) {
	if r.VerifyCredentials == nil || !r.VerifyCredentials(userID, credentials) {
		return StatusAuthFailed, nil, nil
	}
	texp := r.Now().Add(r.Validity).Unix()
	ct, err := EncryptPolicy(NewPolicy(userID, permissions, lType, texp), r.Kindex)
	if err != nil {
		return "", nil, err
	}
	if err := r.Chain.GrantAccess(userID, ct); err != nil {
		return "", nil, err
	}
	tok, err := EncryptToken(UserToken{UserID: userID, Permissions: slices.Clone(permissions), Texp: texp}, r.Kauth)
	if err != nil {
		return "", nil, err
	}
	return StatusRegistered, tok, nil
}

func appendString(b []byte, s string) []byte {
	b = binary.BigEndian.AppendUint32(b, uint32(len(s)))
	return append(b, s...)
}

func encodePermissions(b []byte, perms []string) []byte {
	b = binary.BigEndian.AppendUint32(b, uint32(len(perms)))
	for _, p := range perms {
		b = appendString(b, p)
	}
	return b
}

func readString(b []byte) (string, []byte, bool) {
	if len(b) < 4 {
		return "", nil, false
	}
	n := binary.BigEndian.Uint32(b)
	if uint64(n) > uint64(len(b)-4) {
		return "", nil, false
	}
	return string(b[4 : 4+n]), b[4+n:], true
}
